@import url('https://fonts.googleapis.com/css2?family=jost:wght@400;600;700&family=poppins:wght@400;600;700&display=swap');

/* ===== Reset & page ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2B2B2B;
  font-family: "Jost", sans-serif;
}

/* ===== Ad wrapper ===== */
#ad-300x250 {
  width: 300px;
  height: 250px;
  position: relative;
  overflow: hidden;
  font-family: "Jost", sans-serif;
  cursor: pointer;
}

/* ===== Background slide track ===== */
.slide-track {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.slide {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center top;
  opacity: 0;
  transition: opacity 0.9s ease;
}

.slide.active {
  opacity: 1;
}

/* ===== Gradient overlay ===== */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(
    180deg,
    rgba(0, 80, 160, 0.45) 0%,
    rgba(0, 0, 0, 0.05) 40%,
    rgba(43, 43, 43, 0.72) 100%
  );
}

/* ===== Eyebrow ===== */
.eyebrow {
  position: absolute;
  top: 10px;
  left: 12px;
  z-index: 10;
  font-family: "Jost", sans-serif;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #FFD200;
  background: rgba(0, 80, 160, 0.75);
  padding: 2px 6px;
  border-radius: 2px;
}

/* ===== Logo ===== */
.logo-wrap {
  position: absolute;
  top: 8px;
  right: 10px;
  z-index: 10;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 4px;
  padding: 3px 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo {
  height: 32px;
  width: auto;
  display: block;
}

/* ===== Headline ===== */
.headline {
  position: absolute;
  top: 60px;
  left: 12px;
  right: 12px;
  z-index: 10;
  font-family: "Poppins", sans-serif;
  font-size: 32px;
  font-weight: 800;
  line-height: 1.05;
  color: #FFFFFF;
  text-shadow: 0 2px 8px rgba(43, 43, 43, 0.7);
  letter-spacing: -0.5px;
  animation: slideUp 0.7s ease both;
}

.headline em {
  font-style: italic;
  color: #FFD200;
  -webkit-text-stroke: 0.5px rgba(238, 124, 27, 0.6);
}

/* ===== Subhead ===== */
.subhead {
  position: absolute;
  top: 102px;
  left: 12px;
  z-index: 10;
  font-family: "Poppins", sans-serif;
  font-size: 16px;
  font-weight: 700;
  color: #EE7C1B;
  text-shadow: 0 1px 4px rgba(43, 43, 43, 0.6);
  animation: slideUp 0.7s 0.15s ease both;
}

/* ===== Body copy ===== */
.body-copy {
  position: absolute;
  top: 128px;
  left: 12px;
  right: 12px;
  z-index: 10;
  font-family: "Jost", sans-serif;
  font-size: 10px;
  font-weight: 600;
  color: #FFF4DE;
  letter-spacing: 0.4px;
  animation: slideUp 0.7s 0.25s ease both;
}

/* ===== CTA ===== */
.cta-btn {
  position: absolute;
  bottom: 36px;
  left: 12px;
  z-index: 10;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  background: #E2001A;
  border-radius: 24px;
  padding: 0;
  box-shadow: 0 3px 10px rgba(226, 0, 26, 0.5);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  animation: popIn 0.5s 0.45s ease both;
  margin-bottom: 20px;
}

.cta-btn:hover {
  background: #EE7C1B;
  transform: scale(1.06);
  box-shadow: 0 5px 14px rgba(238, 124, 27, 0.55);
}

.cta-btn:active {
  transform: scale(0.97);
}

.cta-label {
  font-family: "Poppins", sans-serif;
  font-size: 11px;
  font-weight: 600;
  color: #FFFFFF;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  padding: 8px 16px;
  display: block;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

/* ===== Slide dots ===== */
.dots {
  position: absolute;
  bottom: 36px;
  right: 10px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
  border: none;
  cursor: pointer;
  padding: 0;
  transition: background 0.2s ease, transform 0.2s ease;
}

.dot.active {
  background: #FFD200;
  transform: scale(1.3);
}

.dot:hover {
  background: rgba(255, 210, 0, 0.7);
}

/* ===== Footer ===== */
.ad-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 10;
  background: rgba(0, 80, 160, 0.88);
  padding: 4px 12px;
  height: 24px;
  display: flex;
  align-items: center;
}

.ad-footer span {
  font-family: "Jost", sans-serif;
  font-size: 7.5px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.88);
  letter-spacing: 0.3px;
  text-transform: uppercase;
}

/* ===== Progress bar ===== */
.progress-bar {
  position: absolute;
  bottom: 24px;
  left: 0;
  height: 2px;
  background: #FFD200;
  z-index: 11;
  width: 0%;
  transition: width linear;
}

/* ===== Keyframes ===== */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes popIn {
  0%   { opacity: 0; transform: scale(0.8); }
  70%  { transform: scale(1.07); }
  100% { opacity: 1; transform: scale(1); }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  .slide { transition: none; }
  .headline, .subhead, .body-copy, .cta-btn { animation: none; }
  .cta-btn:hover { transform: none; }
  .progress-bar { transition: none; }
}

